public void makeWorkflow()
{
    TFMWorkflowsTable wfTable = this.makeEntry(TFMConstants::WorkflowStandard());

    wfTable.addStepBlock(classStr(TFMWorkflowBlockDimensions));
    wfTable.addStepBlock(classStr(TFMWorkflowBlockQuantity));

    TFMGenericParms::CreateOrUpdateParameter(TFMWorkflowsTable::GetWorkflowDomainName(wfTable.WorkflowName), 'SerialNumber', 'validationWarningType', TFMOverDeliveryValidation::None);
    TFMGenericParms::CreateOrUpdateParameter(TFMWorkflowsTable::GetWorkflowDomainName(wfTable.WorkflowName), 'ToBin', 'validationWarningType', TFMOverDeliveryValidation::Warn);
    TFMGenericParms::CreateOrUpdateParameter(TFMWorkflowsTable::GetWorkflowDomainName(wfTable.WorkflowName), 'FromBin', 'validationWarningType', TFMOverDeliveryValidation::Warn);
}
